package com.clinic.appointment.domain;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="outbox_events") public class OutboxEvent{public enum Status{PENDING,RETRY,SENT,FAILED}@Id private UUID id;@Column(nullable=false,unique=true)private String eventKey;@Column(nullable=false)private String target;@Column(nullable=false,columnDefinition="text")private String payload;@Enumerated(EnumType.STRING)@Column(nullable=false)private Status status;@Column(nullable=false)private int attempts;@Column(nullable=false)private Instant nextAttemptAt;private String lastError;@Column(nullable=false,updatable=false)private Instant createdAt;protected OutboxEvent(){}public OutboxEvent(String key,String target,String payload){id=UUID.randomUUID();eventKey=key;this.target=target;this.payload=payload;status=Status.PENDING;attempts=0;nextAttemptAt=Instant.now();createdAt=Instant.now();}public String getTarget(){return target;}public String getPayload(){return payload;}public void sent(){status=Status.SENT;lastError=null;}public void failed(String error){attempts++;lastError=error==null?"Unknown":error.substring(0,Math.min(900,error.length()));if(attempts>=8)status=Status.FAILED;else{status=Status.RETRY;nextAttemptAt=Instant.now().plusSeconds((long)Math.pow(2,Math.min(attempts,7))*15);}}}
